			if (i_vpns_type == 3) {
				int i_wg_port = nvram_safe_get_int("vpns_wg_port", 51820, 1, 65535);
				fprintf(fp, "-A %s -p %s --dport %d -j %s\n", dtype, "udp", i_wg_port, logaccept);
			} else
